/** Public marketing sample generated by the same renderer as issued certificates. No records are written. */
import fs from "node:fs/promises";
import { execFileSync } from "node:child_process";
import { PDFDocument, degrees, rgb } from "pdf-lib";
import sharp from "sharp";
import { createCertificatePdf } from "../src/lib/certificate-pdf.server.ts";
const output = "public/images/home";
const temp = await fs.mkdtemp("/tmp/tgpi-home-certificate-");
await fs.mkdir(output, { recursive: true });
for (const locale of ["pt", "en"]) {
  const pt = locale === "pt";
  const bytes = await createCertificatePdf({
    id: "TGPI-DEMO-HOME-2026", publicName: pt ? "Seu Nome Completo" : "Your Full Name",
    courseTitle: pt ? "Inglês Global: Viva, Trabalhe e Sinta-se em Casa no Exterior" : "Global English: Live, Work and Feel at Home Abroad",
    courseVersion: "2026.2", documentNature: "TGPI learning certificate",
    completedAt: "2026-11-10T12:00:00Z", issuedAt: "2026-11-10T12:00:00Z", assessmentScore: 90, masteryThreshold: 70, learningHours: 700 / 60,
    professionalEvidence: { instructionLanguage: "en", certificateLanguage: pt ? "pt-BR" : "en", sharing: false, rubricVersion: "sample" },
    identityEvidence: { globalKeyId: "TGPI-DEMO-ONLY" }, skills: [{ name: pt ? "Inglês aplicado" : "Applied English" }], status: "active", integrityVerified: true,
  });
  const pdf = await PDFDocument.load(bytes);
  const page = pdf.getPage(0);
  page.drawText(pt ? "AMOSTRA - SEM VALIDADE" : "SAMPLE - NOT A VALID CREDENTIAL", { x: 140, y: 160, size: pt ? 35 : 27, rotate: degrees(18), color: rgb(.4,.25,.1), opacity:.2 });
  const path = `${temp}/${locale}`;
  await fs.writeFile(`${path}.pdf`, await pdf.save());
  execFileSync("pdftoppm", ["-scale-to-x", "1684", "-scale-to-y", "1191", "-singlefile", "-png", `${path}.pdf`, path]);
  await sharp(`${path}.png`).webp({ quality: 90 }).toFile(`${output}/certificate-academic-2026-5-${locale}.webp`);
}
console.log("Rendered two watermarked certificate samples. No credentials issued.");
